action.command:
powershell -NoProfile -Command @"
# Parse input from Kiro
`$input = [System.IO.StreamReader]::new([System.Console]::OpenStandardInput()).ReadToEnd() | ConvertFrom-Json
`$toolName = `$input.tool.name
`$params = `$input.tool.arguments

# Track if we should block
`$shouldBlock = `$false
`$blockReason = ""

# DETERMINISTIC SAFETY CHECK 1: Block deletion of critical files
if (`$toolName -eq "delete_file") {
  `$targetFile = `$params.targetFile

  # Define critical file patterns
  `$criticalPatterns = @(
    'package\.json',
    'tsconfig.*\.json',
    'pyproject\.toml',
    '\.env(\.|$)',
    'docker-compose.*\.ya?ml',
    'Dockerfile',
    'src[/\\](app|main|index)\.',
    'src[/\\]__init__\.py',
    '(requirements|setup|poetry)\.txt',
    'next\.config\.',
    'vite\.config\.',
    'vitest\.config\.',
    'jest\.config\.',
    '\.github[/\\]workflows[/\\].*\.ya?ml'
  )

  foreach (`$pattern in `$criticalPatterns) {
    if (`$targetFile -match `$pattern) {
      `$shouldBlock = `$true
      `$blockReason = "Critical file cannot be deleted: `$targetFile"
      break
    }
  }
}

# DETERMINISTIC SAFETY CHECK 2: Warn on .env modifications without backup context
# (Advisory only - do not block; agent has context)
if (`$toolName -in @("str_replace", "fs_write", "fs_append")) {
  `$targetPath = `$params.path
  if (`$targetPath -match "\.env(\.|$)") {
    # Log advisory (exit 0, allow operation)
    Write-Warning "Modifying secrets file: `$targetPath. Ensure backup exists before deployment."
  }
}

# OUTPUT: Decision
if (`$shouldBlock) {
  `$decision = @{
    hookSpecificOutput = @{
      permissionDecision = "ask"
      permissionDecisionReason = `$blockReason
    }
  } | ConvertTo-Json -Depth 10
  Write-Output `$decision
  exit 0  # Hook processed; Kiro will ask user for confirmation
} else {
  exit 0  # Allow tool to proceed
}
"@
